import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

# ---------- Naive CUDA kernel for transposed 2D convolution (output pixel -> sum over input patch) ----------
transpose_conv2d_kernel = """
#include <torch/extension.h>
#include <cuda_runtime.h>

__global__ void transpose_conv2d_kernel(
    const float* input,
    const float* weight,   // [out_channels, in_channels, kH, kW]
    const float* bias,
    int B, int C_out, int H_in, int W_in,
    int kernel_h, int kernel_w,
    int stride_h, int stride_w,
    int padding_h, int padding_w,
    int output_padding_h, int output_padding_w,
    int dilation_h, int dilation_w) {

    const int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx < B * C_out * H_out * W_out) {
        // decode multi-index
        int tmp = idx;
        int b = tmp / (C_out * H_out * W_out);
        tmp %= (C_out * H_out * W_out);
        int oc = tmp / (H_out * W_out);
        tmp %= (H_out * W_out);
        int oy = tmp % W_out;

        // input patch start coordinates
        int in_y0 = (oy * stride_h - padding_h - output_padding_h) / dilation_h;
        int in_x0 = (oy * stride_w - padding_w - output_padding_w) / dilation_w;

        float sum = 0.0f;
        for (int ci = 0; ci < in_channels; ++ci) {
            // iterate over kernel region
            for (int ky = 0; ky < kernel_h; ++ky) {
                int i_y = in_y0 + ky * dilation_h;
                if (i_y < 0 || i_y >= H_in) continue;
                for (int kx = 0; kx < kernel_w; ++kx) {
                    int i_x = in_x0 + kx * dilation_w;
                    if (i_x < 0 || i_x >= W_in) continue;
                    float val = input[b * in_channels * H_in * W_in + ci * H_in * W_in + i_y * W_in + i_x];
                    sum += val * weight[oc * in_channels * kernel_h * kernel_w + ci * kernel_h * kernel_w + ky * kernel_w + kx];
                }
            }
        }

        if (bias != False) {
            out[b * out_channels * H_out * W_out + oc * H_out * W_out + oy * W_out + ox] = sum + bias;
        } else {
            out[b * out_channels * H_out * W_out + oc * H_out * W_out + oy * W_out + ox] = sum;
        }
    }
}
"""

# ---------- Compile inline for transposed convolution ----------
transpose_conv2d_cpp_source = (
    "torch::Tensor transpose_conv2d_cuda(torch::Tensor x);"
)

elementwise_add_cuda = None  # not needed

transpose_conv2d_cuda = load_inline(
    name="transpose_conv2d_cuda",
    cpp_sources=transpose_conv2d_cpp_source,
    cuda_sources=transpose_conv2d_kernel,
    functions=["transpose_conv2d_cuda"],
    verbose=True,
)

class ModelNew(nn.Module):
    def __init__(self, in_channels: int, out_channels: int, kernel_size: tuple = (3, 5),
                 stride: tuple = (1, 1), padding: tuple = (0, 0), output_padding: tuple = (0, 0),
                 dilation: tuple = (1, 1), groups: int = 1, bias: bool = False):
        super().__init__()
        self.transpose_conv2d_cuda = transpose_conv2d_cuda

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        return self.transpose_conv2d_cuda(x)
